<script setup>
import {ref,onMounted} from 'vue'
import {api,downloadFile} from './api'
const props=defineProps({permissions:{type:Array,default:()=>[]}})
const can=p=>props.permissions.includes(p)
const rows=ref([]),q=ref(''),category=ref(''),validity=ref(''),referenceDate=ref(''),categories=ref([]),busy=ref(false),more=ref(false),error=ref(''),notice=ref(''),form=ref(null),pdf=ref(null)
const statuses={unknown:'待核验',current:'现行（已核验）',partial:'部分条文废止',historical:'历史版本',withdrawn:'已废止'}
function newForm(s=null){pdf.value=null;form.value=s?{standardNo:s.standard_no,edition:s.edition,title:s.title,category:s.category,publicationYear:String(s.publication_year||''),effectiveOn:s.effective_on||'',withdrawnOn:s.withdrawn_on||'',validity:s.validity,aliases:s.aliases,sourceUrl:s.source_url,accessUrl:s.access_url||'',notes:s.notes,verified:false}:{standardNo:'',edition:'',title:'',category:'',publicationYear:'',effectiveOn:'',withdrawnOn:'',validity:'unknown',aliases:'',sourceUrl:'https://www.1190119.com/',accessUrl:'',notes:'',verified:false}}
async function load(reset=true){if(busy.value)return;busy.value=true;error.value='';try{const p=new URLSearchParams({q:q.value,category:category.value,validity:validity.value,referenceDate:referenceDate.value,includeInactive:String(can('report:standard:write')),offset:String(reset?0:rows.value.length),limit:'50'});const result=await api('/fire-standards?'+p);rows.value=reset?result.rows:[...rows.value,...result.rows];more.value=result.hasMore;categories.value=await api('/fire-standards/categories')}catch(e){error.value=e.message}finally{busy.value=false}}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const data={...form.value};if(pdf.value){const f=new FormData();f.append('file',pdf.value);data.fileId=(await api('/files',{method:'POST',body:f})).id}await api('/fire-standards',{method:'POST',body:JSON.stringify(data)});form.value=null;pdf.value=null;notice.value='已保存独立资料修订，历史引用保持不变'}catch(e){error.value=e.message}finally{busy.value=false}await load()}
async function toggle(s){if(busy.value)return;busy.value=true;try{await api('/fire-standards/'+s.id+'/active',{method:'PUT',body:JSON.stringify({active:!s.active})})}catch(e){error.value=e.message}finally{busy.value=false}await load()}
async function download(s){try{await downloadFile(s.file_id,s.original_name)}catch(e){error.value=e.message}}
onMounted(load)
</script>
<template><section class="std-page"><header><h2>消防规范资料库</h2><p>来源仅限消防资源网及其指引的消防规范网。目录候选须人工核对规范原文、实施/废止日期、修订公告与条文范围后才能选用。历史版本保留，不自动判断法律适用性。</p><a href="https://www.1190119.com/" target="_blank" rel="noopener noreferrer">打开消防资源网</a></header>
<p v-if="error" role="alert">{{error}}</p><p v-if="notice">{{notice}}</p>
<div class="std-toolbar"><input v-model="q" placeholder="名称、编号、别名" @keydown.enter.prevent="load()"><select v-model="category" @change="load()"><option value="">全部类别</option><option v-for="c in categories" :key="c">{{c}}</option></select><select v-model="validity" @change="load()"><option value="">全部状态</option><option v-for="(v,k) in statuses" :key="k" :value="k">{{v}}</option></select><label>参考日期 <input type="date" v-model="referenceDate" @change="load()"></label><button :disabled="busy" @click="load()">搜索</button><button v-if="can('report:standard:write')" @click="newForm()">新增规范版本</button></div>
<form v-if="form" class="std-form" @submit.prevent="save"><label>规范编号<input v-model="form.standardNo" required maxlength="80"></label><label>版次 / 修订版<input v-model="form.edition" maxlength="80"></label><label>名称<input v-model="form.title" required maxlength="240"></label><label>类别<input v-model="form.category" required maxlength="100" list="std-category"><datalist id="std-category"><option v-for="c in categories" :key="c" :value="c"/></datalist></label><label>发布年份<input v-model="form.publicationYear" maxlength="4"></label><label>实施日期<input v-model="form.effectiveOn" type="date"></label><label>废止日期（未知则留空）<input v-model="form.withdrawnOn" type="date"></label><label>规范状态<select v-model="form.validity"><option v-for="(v,k) in statuses" :key="k" :value="k">{{v}}</option></select></label><label class="wide">旧编号 / 别名<input v-model="form.aliases" maxlength="240"></label><label class="wide">消防资源网来源页面<input v-model="form.sourceUrl" required type="url"></label><label class="wide">规范原文入口<input v-model="form.accessUrl" type="url"></label><label class="wide">核验说明 / 条文变化 / 过渡期<textarea v-model="form.notes" rows="3" maxlength="2000"></textarea></label><label v-if="can('file:upload')" class="wide">获准保存的原文 PDF（可选）<input type="file" accept="application/pdf" @change="pdf=$event.target.files?.[0]||null"></label><label class="wide"><span><input v-model="form.verified" type="checkbox">已人工核对该版本原文与来源，确认元数据；不代表适用于任何特定工程。</span></label><button :disabled="busy">保存新修订</button><button type="button" @click="form=null">取消</button></form>
<article v-for="s in rows" :key="s.id" class="std-row"><div><b>《{{s.title}}》 {{s.standard_no}} {{s.edition}}</b><small>{{s.category}} · {{s.verified?statuses[s.validity]:'待人工核验'}} · 修订 v{{s.revision_no}} · {{s.active?'启用':'停用'}}</small><small>实施：{{s.effective_on||'待核'}}　废止：{{s.withdrawn_on||'未录入'}} · {{s.notes}}</small><div class="std-toolbar"><a :href="s.source_url" target="_blank" rel="noopener noreferrer">来源页面</a><a v-if="s.access_url" :href="s.access_url" target="_blank" rel="noopener noreferrer">原文入口</a><button v-if="s.file_id&&can('file:read')" @click="download(s)">PDF原件</button></div></div><div v-if="can('report:standard:write')" class="std-toolbar"><button @click="newForm(s)">核验 / 新修订</button><button :disabled="busy" @click="toggle(s)">{{s.active?'停用':'启用'}}</button></div></article><button v-if="more" :disabled="busy" @click="load(false)">加载更多</button></section></template>
<style scoped>.std-page{display:grid;gap:14px}.std-page h2,.std-page p{margin:0}.std-page p,.std-page small{color:#64748b;font-size:12px;line-height:1.7}.std-toolbar{display:flex;gap:8px;align-items:center;flex-wrap:wrap}.std-form{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:16px;background:white;border:1px solid #e2e8f0;border-radius:10px}.std-form label{display:grid;gap:5px;font-size:12px}.std-form .wide{grid-column:1/-1}.std-page input:not([type=checkbox]),.std-page select,.std-page textarea,.std-page button{min-width:0;border:1px solid #dfe6ef;background:white;border-radius:7px;padding:8px;font:inherit;color:inherit}.std-row{display:flex;justify-content:space-between;gap:12px;padding:14px;background:white;border:1px solid #e2e8f0;border-radius:10px}.std-row>div:first-child{display:grid;gap:5px}@media(max-width:700px){.std-form{grid-template-columns:1fr}.std-row{flex-direction:column}}</style>